function modal(title,content,submitLabel=t('save'),{wide=false,form='',id=''}={}){
  const root=document.getElementById('modalRoot');
  root.innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button class="close-modal" type="button" data-action="close-modal" aria-label="${esc(t('close'))}">×</button></div><form data-form="${esc(form)}" data-id="${esc(id)}"><div class="modal-body">${content}</div><div class="modal-footer"><button class="ghost-button" type="button" data-action="close-modal">${esc(t('cancel'))}</button><button class="primary-button" type="submit">${esc(submitLabel)}</button></div></form></section></div>`;
  root.querySelectorAll('[data-action="close-modal"]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();root.innerHTML='';}));
  root.querySelector('.modal-backdrop')?.addEventListener('click',event=>{if(event.target===event.currentTarget){event.preventDefault();event.stopPropagation();root.innerHTML='';}});
}

function localDateInput(iso){
  if(!iso)return currentDateText();
  if(state.calendar==='gregorian')return iso.slice(0,10);
  const parts=new Intl.DateTimeFormat('en-US-u-ca-persian-nu-latn',{year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(`${iso.slice(0,10)}T12:00:00`));
  return `${parts.find(x=>x.type==='year').value}/${parts.find(x=>x.type==='month').value.padStart(2,'0')}/${parts.find(x=>x.type==='day').value.padStart(2,'0')}`;
}

function accountOptions(selected=''){
  return `<option value="">${esc(t('choose'))}</option>`+state.accounts.filter(a=>!a.archived).map(a=>`<option value="${a.id}" ${String(a.id)===String(selected)?'selected':''}>${esc(a.name)}</option>`).join('');
}
function categoryOptions(kind,selected=''){
  return `<option value="">${esc(t('choose'))}</option>`+state.categories.filter(c=>c.enabled&&c.kind===kind).map(c=>`<option value="${c.id}" ${String(c.id)===String(selected)?'selected':''}>${esc(c.name.trim())}</option>`).join('');
}

async function transactionModal(kind='expense',id=''){
  const [cats,accounts]=await Promise.all([api('/categories'),api('/accounts')]);state.categories=cats;state.accounts=accounts;
  const row=id?await api(`/transactions/${id}`):null;const currentKind=row?.kind||kind;
  const readonly=false;
  const fields=`${row?`<input type="hidden" name="id" value="${row.id}">`:''}<div class="form-grid">
    <div class="form-field"><label>${esc(t('type'))}</label><select name="kind" class="field-select" ${readonly?'disabled':''}><option value="income" ${currentKind==='income'?'selected':''}>${esc(t('income'))}</option><option value="expense" ${currentKind==='expense'?'selected':''}>${esc(t('expense'))}</option></select>${readonly?`<input type="hidden" name="kind" value="${row.kind}">`:''}</div>
    <div class="form-field"><label>${esc(t('title'))}</label><input class="field" name="title" value="${esc(row?.title||'')}" maxlength="180" required ${readonly?'readonly':''}></div>
    ${dateInput(t('date'),'date',row?localDateInput(row.date):currentDateText())}
    <div class="form-field"><label>${esc(t('time'))}</label><input class="field" name="time" type="time" value="${esc(row?.time||'')}" ${readonly?'readonly':''}><span class="form-hint">24h</span></div>
    <div class="form-field"><label>${esc(t('amount'))}</label><input class="field" name="amount" inputmode="decimal" value="${esc(row?String(row.amount||'').replace(/^-/, ''): '')}" placeholder="0" required ${readonly?'readonly':''}></div>
    <div class="form-field"><label>${esc(t('category'))}</label><select class="field-select category-choice" name="category_id" ${readonly?'disabled':''}>${categoryOptions(currentKind,row?.category_id)}</select>${readonly&&row?.category_id?`<input type="hidden" name="category_id" value="${row.category_id}">`:''}</div>
    <div class="form-field"><label>${esc(t('account'))}</label><select class="field-select" name="account_id" ${readonly?'disabled':''}>${accountOptions(row?.account_id)}</select>${readonly&&row?.account_id?`<input type="hidden" name="account_id" value="${row.account_id}">`:''}</div>
    <div class="form-field"><label>${esc(t('tags'))}</label><input class="field" name="tags" value="${esc(row?.tags?.join(', ')||'')}" placeholder="${state.lang==='fa'?'با ویرگول جدا کنید':'Comma-separated'}" ${readonly?'readonly':''}></div>
    <div class="form-field span-2"><label>${esc(t('note'))}</label><textarea class="field-textarea" name="note" maxlength="2000" ${readonly?'readonly':''}>${esc(row?.note||'')}</textarea></div>
    <div class="form-field span-2"><label>${esc(t('subcategory'))}</label><input class="field" name="subcategory" value="${esc(row?.subcategory||'')}" ${readonly?'readonly':''}></div>
    ${readonly?`<div class="form-field span-2"><div class="source-note">${esc(t('historicalReadonly'))} · ${esc(row.source_sheet||'')} / ${esc(row.source_row||'')} · raw: ${esc(row.raw_amount)}</div></div>`:''}
    ${row?`<div class="form-field span-2"><div class="panel-note">${esc(t('includeAll'))}</div><div class="form-grid"><label class="setting-row"><span>${esc(t('includeAll'))}</span><input type="checkbox" name="inc_all" ${row.inclusion?.all?'checked':''}></label><label class="setting-row"><span>${esc(t('reportExclusion'))}</span><input type="checkbox" name="inc_report" ${row.inclusion?.report?'checked':''}></label><label class="setting-row"><span>${esc(t('budgetExclusion'))}</span><input type="checkbox" name="inc_budget" ${row.inclusion?.budget?'checked':''}></label><label class="setting-row"><span>${esc(t('forecastExclusion'))}</span><input type="checkbox" name="inc_forecast" ${row.inclusion?.forecast?'checked':''}></label><label class="setting-row"><span>${esc(t('operationalExclusion'))}</span><input type="checkbox" name="inc_operational" ${row.inclusion?.operational?'checked':''}></label></div></div>`:''}
  </div>`;
  modal(row?(readonly?t('historicalReadonly'):t('edit')):t('newTransaction'),fields,t('save'),{form:'transaction',id:row?.id||''});
  document.querySelector('[data-form="transaction"] select[name="kind"]')?.addEventListener('change',e=>{const select=document.querySelector('.category-choice');if(select)select.innerHTML=categoryOptions(e.target.value);});
}

