function importModal(file,headers,preview=null){
  const guess=(keys)=>{const idx=headers.findIndex(h=>keys.some(k=>String(h).toLowerCase().includes(k)));return idx>=0?String(idx):''};
  const mapping=preview?.mapping||{date:guess(['date','تاریخ']),time:guess(['time','ساعت']),amount:guess(['amount','مبلغ']),kind:guess(['type','نوع']),category:guess(['category','دسته']),title:guess(['title','عنوان']),note:guess(['note','توضیح'])};
  const field=(name,required=false)=>`<div class="form-field"><label>${esc(t(name==='kind'?'type':name))}${required?' *':''}</label><select class="field-select" name="map_${name}" ${required?'required':''}><option value="">${esc(t('choose'))}</option>${headers.map((h,i)=>`<option value="${i}" ${String(mapping[name])===String(i)?'selected':''}>${esc(h||`Column ${i+1}`)}</option>`).join('')}</select></div>`;
  const columns=`${field('date',true)}${field('amount',true)}${field('kind',true)}${field('category',true)}${field('title')}${field('time')}${field('note')}<div class="form-field"><label>${esc(t('calendarSystem'))}</label><select class="field-select" name="calendar"><option value="jalali" ${state.calendar==='jalali'?'selected':''}>${esc(t('jalali'))}</option><option value="gregorian" ${state.calendar==='gregorian'?'selected':''}>${esc(t('gregorian'))}</option></select></div><div class="form-field span-2"><label><input type="checkbox" name="has_header" checked> ${esc(t('firstRowHeader'))}</label></div>`;
  const previewHtml=preview?`<div class="source-note">${esc(t('importRows'))}: ${formatNumber(preview.valid,0)} · ${esc(t('duplicates'))}: ${formatNumber(preview.duplicates,0)} · ${esc(t('errors'))}: ${formatNumber(preview.errors,0)}</div><div class="table-wrap" style="max-height:240px;margin-top:10px"><table><thead><tr><th>#</th><th>${esc(t('date'))}</th><th>${esc(t('type'))}</th><th>${esc(t('amount'))}</th><th>${esc(t('category'))}</th><th>${esc(t('status'))}</th></tr></thead><tbody>${preview.rows.slice(0,30).map(r=>`<tr><td>${r.row}</td><td>${esc(r.date||'—')}</td><td>${esc(r.kind||'—')}</td><td>${esc(r.amount)}</td><td>${esc(r.category)}</td><td>${esc(r.issues.join(state.lang==='fa'?'؛ ':'; ')|| (r.duplicate?t('duplicates'):t('enabled')))}</td></tr>`).join('')}</tbody></table></div>`:'';
  modal(t('columnMapping'),`<input type="hidden" name="filename" value="${esc(file.name)}"><input type="hidden" name="content_base64" value="${esc(file.base64)}"><div class="form-grid">${columns}</div>${previewHtml}`,preview?t('commitImport'):t('previewImport'),{form:preview?'import-commit':'import-preview',wide:true});
}

function bindGlobal(){
  if(globalHandlersBound)return;globalHandlersBound=true;
  document.addEventListener('click',handleClick);
  document.addEventListener('submit',handleSubmit);
  document.addEventListener('change',handleChange);
  document.getElementById('languageBtn').addEventListener('click',async()=>{try{await api('/settings',{method:'PATCH',body:{language:state.lang==='fa'?'en':'fa'}});await boot();}catch(e){toast(e.message,'error')}});
  document.getElementById('quickAddBtn').addEventListener('click',()=>transactionModal('expense'));
  document.getElementById('notificationBtn').addEventListener('click',showNotifications);
  document.getElementById('logoutBtn').addEventListener('click',async()=>{try{await api('/auth/logout',{method:'POST',body:{}});location.replace('/login');}catch(error){toast(error.message,'error');}});
  document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('mobileNav').classList.toggle('expanded'));
}

async function handleSubmit(event){
  const form=event.target.closest('form[data-form]');if(!form)return;
  event.preventDefault();const kind=form.dataset.form,id=form.dataset.id;const fd=new FormData(form);const get=(key)=>String(fd.get(key)??'').trim();
  try{
    if(kind==='password-change'){await api('/auth/password',{method:'POST',body:{current_password:String(fd.get('current_password')??''),new_password:String(fd.get('new_password')??'')}});form.reset();toast(t('passwordChanged'),'success');return;}
    if(kind==='transaction'){
      const txId=get('id')||id;
      const payload={kind:get('kind'),title:get('title'),amount:get('amount'),date:await inputDateToIso(get('date'),state.calendar),calendar:'gregorian',time:get('time'),category_id:get('category_id')||null,account_id:get('account_id')||null,note:get('note'),subcategory:get('subcategory'),tags:get('tags')};
      if(txId)await api(`/transactions/${txId}`,{method:'PATCH',body:payload});else await api('/transactions',{method:'POST',body:payload});
      closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='transaction-filter'){
      const from=get('from'),to=get('to');state.filters={...state.filters,q:get('q'),kind:get('kind'),category:get('category'),account_id:get('account_id'),included:get('included'),min_amount:get('min_amount'),max_amount:get('max_amount'),tags:get('tags'),sort:get('sort'),dir:get('dir'),fromInput:from,toInput:to,fromIso:from?await inputDateToIso(from,state.calendar):'',toIso:to?await inputDateToIso(to,state.calendar):''};state.pageNumber=1;await renderPage();return;
    }
    if(kind==='report-filter'){
      const from=get('from'),to=get('to');state.filters.reportFrom=from;state.filters.reportTo=to;state.filters.reportFromIso=from?await inputDateToIso(from,state.calendar):'';state.filters.reportToIso=to?await inputDateToIso(to,state.calendar):'';state.filters.reportGroup=get('group')||'month';await renderPage();return;
    }
    if(kind==='cashflow-filter'){
      const from=get('from'),to=get('to');state.filters.cashflow={fromInput:from,toInput:to,fromIso:from?await inputDateToIso(from,state.calendar):'',toIso:to?await inputDateToIso(to,state.calendar):''};await renderPage();return;
    }
    if(kind==='compare-filter'){
      const from=get('from'),to=get('to');if(!from||!to)throw new Error(t('reportPeriod'));state.filters.compare={fromInput:from,toInput:to,fromIso:await inputDateToIso(from,state.calendar),toIso:await inputDateToIso(to,state.calendar),unit:get('unit'),periods:get('periods')};await renderPage();return;
    }
    if(kind==='category'){
      const payload={name:get('name'),kind:get('kind')||state.categories.find(x=>String(x.id)===String(id))?.kind||'expense',color:get('color'),parent_id:get('parent_id')||null,enabled:get('enabled')!=='0'};
      if(id)await api(`/categories/${id}`,{method:'PATCH',body:payload});else await api('/categories',{method:'POST',body:payload});
      await refreshGlobal(t('saveSuccess'));return;
    }
    if(kind==='delete-category'){
      const moveTo=get('move_to');const result=await api(`/categories/${id}${moveTo?`?move_to=${encodeURIComponent(moveTo)}`:''}`,{method:'DELETE'});document.getElementById('modalRoot').innerHTML='';await refreshGlobal(result.disabled?t('archive'):t('deleteSuccess'));return;
    }
    if(kind==='account'){
      const payload={name:get('name'),kind:get('kind'),opening_balance:get('opening_balance'),currency:get('currency'),note:get('note'),archived:get('archived')==='1'};
      if(id)await api(`/accounts/${id}`,{method:'PATCH',body:payload});else await api('/accounts',{method:'POST',body:payload});
      await refreshGlobal(t('saveSuccess'));return;
    }
    if(kind==='transfer'){
      const payload={from_account_id:get('from_account_id'),to_account_id:get('to_account_id'),amount:get('amount'),date:await inputDateToIso(get('date'),state.calendar),calendar:'gregorian',time:get('time'),note:get('note')};await api('/transfers',{method:'POST',body:payload});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='budget'){
      const thresholds=get('thresholds').split(',').map(x=>Number(x.trim())).filter(Number.isFinite);
      const payload={name:get('name'),category_id:get('category_id')||null,amount:get('amount'),start_date:await inputDateToIso(get('start_date'),state.calendar),end_date:await inputDateToIso(get('end_date'),state.calendar),calendar:'gregorian',thresholds,enabled:get('enabled')!=='0'};
      if(id)await api(`/budgets/${id}`,{method:'PATCH',body:payload});else await api('/budgets',{method:'POST',body:payload});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='recurring'){
      const cat=state.categories.find(c=>String(c.id)===get('category_id'));
      const payload={title:get('title'),kind:get('kind'),amount:get('amount'),category_id:get('category_id')||null,category:cat?.name,account_id:get('account_id')||null,cadence:get('cadence'),interval_n:get('interval_n')||1,start_date:await inputDateToIso(get('start_date'),state.calendar),next_date:await inputDateToIso(get('next_date')||get('start_date'),state.calendar),end_date:get('end_date')?await inputDateToIso(get('end_date'),state.calendar):null,time:get('time'),note:get('note'),calendar:'gregorian'};
      await api('/recurring',{method:'POST',body:payload});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='debt'){
      const payload={kind:get('kind'),party:get('party'),title:get('title'),original_amount:get('original_amount'),due_date:get('due_date')?await inputDateToIso(get('due_date'),state.calendar):null,notes:get('notes'),calendar:'gregorian'};await api('/debts',{method:'POST',body:payload});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='debt-payment'){
      const did=get('debt_id');const payload={amount:get('amount'),date:await inputDateToIso(get('date'),state.calendar),account_id:get('account_id')||null,note:get('note'),calendar:'gregorian'};await api(`/debts/${did}/payments`,{method:'POST',body:payload});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='goal'){
      const payload={name:get('name'),target_amount:get('target_amount'),target_date:get('target_date')?await inputDateToIso(get('target_date'),state.calendar):null,color:get('color'),notes:get('notes'),calendar:'gregorian'};await api('/goals',{method:'POST',body:payload});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='goal-movement'){
      const gid=get('goal_id');const payload={action:get('action'),amount:get('amount'),date:await inputDateToIso(get('date'),state.calendar),account_id:get('account_id')||null,note:get('note'),calendar:'gregorian'};await api(`/goals/${gid}/movements`,{method:'POST',body:payload});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='settings'){
      const payload={language:get('language'),calendar:get('calendar'),currency_unit:get('currency_unit'),theme:get('theme'),accent:get('accent')};await api('/settings',{method:'PATCH',body:payload});document.getElementById('modalRoot').innerHTML='';await boot();toast(t('saveSuccess'),'success');return;
    }
    if(kind==='saved-filter'){
      await api('/filters',{method:'POST',body:{name:get('name'),filters:state.filters}});closeAndRefresh(t('saveSuccess'));return;
    }
    if(kind==='import-preview'){
      const mapping={};for(const name of ['date','amount','kind','category','title','time','note']){const value=get(`map_${name}`);if(value!=='')mapping[name]=Number(value);}
      const preview=await api('/import/preview',{method:'POST',body:{filename:get('filename'),content_base64:get('content_base64'),mapping,calendar:get('calendar'),has_header:fd.has('has_header')}});
      state.importPreview={...preview,mapping};importModal(state.importFile,preview.headers,preview);return;
    }
    if(kind==='import-commit'){
      const result=await api('/import/commit',{method:'POST',body:{rows:state.importPreview?.rows||[]}});state.importPreview=null;state.importFile=null;closeAndRefresh(`${t('importSuccess')} · ${formatNumber(result.imported,0)}`);return;
    }
    if(kind==='notification-read'){
      await api('/notifications/read',{method:'POST',body:{}});closeAndRefresh(t('saveSuccess'));return;
    }
  }catch(error){showFormError(form,error.message);}
}

function showFormError(form,message){
  let node=form.querySelector('.modal-error');if(!node){node=document.createElement('div');node.className='modal-error';form.querySelector('.modal-body')?.prepend(node);}node.textContent=message;
}

function closeAndRefresh(message){document.getElementById('modalRoot').innerHTML='';toast(message,'success');refreshGlobal();}

async function refreshGlobal(message){
  try{const [bootstrap,settings]=await Promise.all([api('/bootstrap'),api('/settings')]);state.accounts=bootstrap.accounts||[];state.categories=bootstrap.categories||[];state.counts=bootstrap.counts||{};state.settingsData=settings;applySettings(settings.settings||{});renderShell();await renderPage();if(message)toast(message,'success');}
  catch(error){toast(error.message,'error');}
}

function handleChange(event){
  const target=event.target;
  if(target.id==='pageSizeSelect'){state.filters.pageSize=Number(target.value);state.pageNumber=1;renderPage();return;}
  if(target.id==='importFile'){importSelected(event);return;}
  if(target.id==='restoreFile'){restoreSelected(event);return;}
  if(target.id==='savedFilterSelect'&&target.value){try{state.filters={...state.filters,...JSON.parse(target.selectedOptions[0].dataset.filters||'{}')};state.pageNumber=1;renderPage();}catch(e){toast(e.message,'error');}}
  if(target.matches('form[data-form="transaction"] select[name="kind"]')){const select=target.form.querySelector('.category-choice');if(select)select.innerHTML=categoryOptions(target.value);}
  if(target.matches('form[data-form="recurring"] select[name="kind"]')){const select=target.form.querySelector('select[name="category_id"]');if(select)select.innerHTML=categoryOptions(target.value);}
}

async function importSelected(event){
  const file=event.target.files?.[0];if(!file)return;
  try{
    const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('File could not be read.'));reader.readAsDataURL(file);});
    state.importFile={name:file.name,base64};state.importPreview=null;
    const initial=await api('/import/preview',{method:'POST',body:{filename:file.name,content_base64:base64,mapping:{date:0,amount:1,kind:2,category:3,title:4,note:5,time:6},calendar:state.calendar,has_header:true}}).catch(()=>null);
    importModal(state.importFile,initial?.headers||[],null);
  }catch(error){toast(error.message,'error');}
  finally{event.target.value='';}
}

async function restoreSelected(event){
  const file=event.target.files?.[0];if(!file)return;
  try{
    const backup=JSON.parse(await file.text());
    if(!confirm(t('restoreConfirm')))return;
    await api('/restore',{method:'POST',body:backup});await boot();toast(t('saveSuccess'),'success');
  }catch(error){toast(error.message,'error');}
  finally{event.target.value='';}
}

async function showNotifications(){
  try{
    const data=await api('/notifications');
    const insights=data.insights.map(x=>`<div class="inline-alert"><span class="alert-icon">◉</span><div><b>${esc(x.title)}</b><div>${esc(x.message)}</div></div></div>`).join('');
    const history=data.history.map(x=>`<div class="recent-row"><div class="type-icon">◉</div><div><div class="recent-title">${esc(x.title)}</div><div class="recent-meta">${esc(x.message)} · ${esc(new Date(x.created_at).toLocaleString(locale(),{hour12:false}))}</div></div></div>`).join('');
    const content=`<div class="panel-head"><div><h3>${esc(t('insights'))}</h3><p>${esc(t('alerts'))}</p></div></div>${insights||`<div class="empty-state">${esc(t('noAlerts'))}</div>`}<div class="panel-head" style="margin-top:14px"><h3>${esc(t('notifications'))}</h3></div>${history||`<div class="subtle">${esc(t('noAlerts'))}</div>`}`;
    modal(t('notifications'),content,t('markRead'),{form:'notification-read'});
  }catch(error){toast(error.message,'error');}
}

async function updateNotificationDot(){const node=document.getElementById('notificationCount');if(!node)return;try{const data=await api('/notifications');node.style.display=data.unread?'block':'none';node.title=data.unread?`${data.unread} ${t('notifications')}`:'';}catch(_){node.style.display='none';}}

function toast(message,type=''){
  const root=document.getElementById('toastRoot');const node=document.createElement('div');node.className=`toast ${type}`;node.textContent=message;root.appendChild(node);setTimeout(()=>node.remove(),3800);
}

boot();

async function handleClick(event){
  const pageButton=event.target.closest('[data-page]');
  if(pageButton){await openPage(pageButton.dataset.page);return;}
  const button=event.target.closest('[data-action]');if(!button)return;
  const action=button.dataset.action,id=button.dataset.id;
  try{
    if(action==='close-modal'){document.getElementById('modalRoot').innerHTML='';return;}
    if(action==='backdrop-close'&&event.target===button){document.getElementById('modalRoot').innerHTML='';return;}
    if(action==='mobile-menu'){document.getElementById('mobileNav').classList.toggle('expanded');return;}
    if(action==='reload'){await renderPage();return;}
    if(action==='quick-income'){await transactionModal('income');return;}
    if(action==='quick-expense'){await transactionModal('expense');return;}
    if(action==='add-category'){await categoryModal();return;}
    if(action==='edit-category'){await categoryModal(id);return;}
    if(action==='delete-category'){categoryDeleteModal(id);return;}
    if(action==='add-account'){accountModal();return;}
    if(action==='edit-account'){accountModal(id);return;}
    if(action==='archive-account'){await api(`/accounts/${id}`,{method:'PATCH',body:{archived:true}});toast(t('saveSuccess'),'success');state.accounts=await api('/accounts');await renderPage();return;}
    if(action==='add-transfer'){transferModal();return;}
    if(action==='add-budget'){await budgetModal();return;}
    if(action==='edit-budget'){await budgetModal(id);return;}
    if(action==='delete-budget'){if(confirm(t('deleteConfirm'))){await api(`/budgets/${id}`,{method:'DELETE'});toast(t('deleteSuccess'),'success');await renderPage();}return;}
    if(action==='add-recurring'){recurringModal();return;}
    if(action==='run-recurring'){const r=await api('/recurring/run-due',{method:'POST',body:{}});toast(`${t('actual')}: ${formatNumber(r.generated,0)}`,'success');await renderPage();return;}
    if(action==='toggle-recurring'){await api(`/recurring/${id}`,{method:'PATCH',body:{active:button.dataset.active==='1'}});toast(t('saveSuccess'),'success');await renderPage();return;}
    if(action==='delete-recurring'){if(confirm(t('deleteConfirm'))){await api(`/recurring/${id}`,{method:'DELETE'});await renderPage();}return;}
    if(action==='add-debt'){debtModal();return;}
    if(action==='debt-payment'){debtPaymentModal(id);return;}
    if(action==='delete-debt'){if(confirm(t('deleteConfirm'))){await api(`/debts/${id}`,{method:'DELETE'});await renderPage();}return;}
    if(action==='debt-history'){const items=await api(`/debts/${id}/payments`);modal(t('paymentHistory'),items.length?`<div class="table-wrap"><table><thead><tr><th>${esc(t('date'))}</th><th>${esc(t('amount'))}</th><th>${esc(t('account'))}</th><th>${esc(t('note'))}</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(shortDate(x.date))}</td><td>${esc(fmt(x.amount))}</td><td>${esc(x.account_name||'—')}</td><td>${esc(x.note)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">${esc(t('noRows'))}</div>`,t('close'),{form:'read-only'});document.querySelector('[data-form="read-only"] .modal-footer .primary-button').type='button';document.querySelector('[data-form="read-only"] .modal-footer .primary-button').dataset.action='close-modal';return;}
    if(action==='add-goal'){goalModal();return;}
    if(action==='goal-movement'){goalMovementModal(id,button.dataset.movement);return;}
    if(action==='archive-goal'){if(confirm(t('deleteConfirm'))){await api(`/goals/${id}`,{method:'DELETE'});await renderPage();}return;}
    if(action==='calendar-prev'||action==='calendar-next'){state.calendarMonth=await shiftMonthKey(state.calendarMonth||monthKey(todayIso(),state.calendar),action==='calendar-prev'?-1:1,state.calendar);await renderPage();return;}
    if(action==='calendar-day'){calendarDayModal(id);return;}
    if(action==='tx-details'){await transactionModal('expense',id);return;}
    if(action==='duplicate-tx'){await api(`/transactions/${id}/duplicate`,{method:'POST',body:{}});toast(t('saveSuccess'),'success');await renderPage();return;}
    if(action==='delete-tx'){if(confirm(t('deleteConfirm'))){await api(`/transactions/${id}`,{method:'DELETE'});toast(t('deleteSuccess'),'success');await renderPage();}return;}
    if(action==='restore-tx'){await api(`/transactions/${id}/restore`,{method:'POST',body:{}});toast(t('saveSuccess'),'success');await renderPage();return;}
    if(action==='toggle-deleted'){state.deletedView=!state.deletedView;await renderPage();return;}
    if(action==='page-prev'){state.pageNumber=Math.max(1,state.pageNumber-1);await renderPage();return;}
    if(action==='page-next'){state.pageNumber++;await renderPage();return;}
    if(action==='select-all'){document.querySelectorAll('.row-check').forEach(x=>x.checked=button.checked);return;}
    if(action==='bulk-delete'){const ids=[...document.querySelectorAll('.row-check:checked')].map(x=>Number(x.value));if(!ids.length){toast(t('selected'),'error');return;}if(confirm(`${t('deleteSelected')} (${ids.length})?`)){const result=await api('/transactions/bulk-delete',{method:'POST',body:{ids}});toast(`${t('deleteSuccess')} · ${result.deleted}`,'success');await renderPage();}return;}
    if(action==='clear-filter'){state.filters={...state.filters,q:'',kind:'',category:'',account_id:'',included:'',min_amount:'',max_amount:'',tags:'',fromInput:'',toInput:'',fromIso:'',toIso:''};state.pageNumber=1;await renderPage();return;}
    if(action==='save-filter'){saveFilterModal();return;}
    if(action==='export-csv'){await download('/exports/transactions.csv'+query(state.page==='transactions'?exportFilters():{}),'dara-transactions.csv');return;}
    if(action==='export-xlsx'){await download('/exports/transactions.xlsx'+query(state.page==='transactions'?exportFilters():{}),'dara-transactions.xlsx');return;}
    if(action==='print'){window.print();return;}
    if(action==='backup'){await download('/backup','dara-finance-backup.json');return;}
    if(action==='choose-restore'){document.getElementById('restoreFile').click();return;}
    if(action==='toggle-notification'){const items={};items[button.dataset.key]={enabled:button.dataset.enabled==='1'};await api('/notifications/settings',{method:'PATCH',body:{items}});toast(t('saveSuccess'),'success');await renderPage();return;}
    if(action==='toggle-calendar'){return;}
  }catch(error){toast(error.message,'error');}
}

function categoryDeleteModal(id){
  const cat=state.categories.find(c=>String(c.id)===String(id));if(!cat)return;
  const options=`<option value="">${esc(t('choose'))}</option>`+state.categories.filter(x=>x.kind===cat.kind&&x.id!==cat.id&&x.enabled).map(x=>`<option value="${x.id}">${esc(x.name.trim())}</option>`).join('');
  modal(t('delete'),`<p class="panel-note">${esc(t('categoryDeleteMove'))}</p><div class="form-field"><label>${esc(t('category'))}</label><select class="field-select" name="move_to">${options}</select></div><div class="source-note" style="margin-top:12px">${esc(cat.name)} · ${formatNumber(cat.transaction_count,0)} ${esc(t('rows'))}</div>`,t('delete'),{form:'delete-category',id});
}

function saveFilterModal(){
  modal(t('saveFilter'),`<div class="form-field"><label>${esc(t('filterName'))}</label><input class="field" name="name" required maxlength="80" placeholder="${esc(t('filterName'))}"></div>`,t('save'),{form:'saved-filter'});
}

async function calendarDayModal(iso){
  const month=monthKey(iso,state.calendar);const data=await api('/calendar'+query({month,calendar:state.calendar}));const rows=data.days[iso]?.transactions||[];
  modal(`${shortDate(iso)} · ${esc(t('transactions'))}`,rows.length?transactionTable(rows):`<div class="empty-state">${esc(t('calendarEmpty'))}</div>`,t('close'),{wide:true,form:'calendar-day'});
  const form=document.querySelector('[data-form="calendar-day"]');form.querySelector('.modal-footer .primary-button').type='button';form.querySelector('.modal-footer .primary-button').dataset.action='close-modal';
}

function exportFilters(){const f=state.filters;return {from:f.fromIso,to:f.toIso,q:f.q,kind:f.kind,category:f.category,account_id:f.account_id,min_amount:f.min_amount,max_amount:f.max_amount,included:f.included,tags:f.tags};}


